12	func TestExitCode(t *testing.T) {
13		cases := []struct {
14			name string
15			err  error
16			want int
17		}{
18			{"nil", nil, 0},
19			{"not-found", client.ErrNotFound, 2},
20			{"wrapped-not-found", fmt.Errorf("fetch: %w", client.ErrNotFound), 2},
21			{"context-cancelled", context.Canceled, 130},
22			{"generic", errors.New("boom"), 3},
23		}
24		for _, c := range cases {
25			t.Run(c.name, func(t *testing.T) {
26				if got := ExitCode(c.err); got != c.want {
27					t.Errorf("ExitCode(%v) = %d, want %d", c.err, got, c.want)
28				}
29			})
30		}
31	}
